--liquibase formatted sql

--changeset dth:050-seed-real-schools
--comment Thay dữ liệu demo bằng 946 trường thật của TP.HCM (Cổng dữ liệu mở).

-- NGUỒN: Cổng dữ liệu mở TP.HCM (opendata.hochiminhcity.gov.vn), bộ dữ liệu
-- "Danh sách các cơ sở giáo dục trên địa bàn Thành phố" do Sở GD&ĐT công bố —
-- cùng tệp mà dự án Jmix dùng (docs/data/hcm-schools.csv), nên hai hệ thống
-- nói về cùng một tập trường.
--
-- PHẠM VI, lấy đúng như Jmix đã chốt: chỉ ba cấp TIỂU HỌC / THCS / THPT và chỉ
-- trường CÔNG LẬP. Bỏ ngoài phạm vi: 1.066 mầm non, 87 trường tư thục, 21
-- trường có yếu tố nước ngoài, 60 đơn vị không có cấp học (GDTX, trường chuyên
-- biệt, lớp bổ túc). Căn cứ lọc là cột `ownership` và `educationLevel` của
-- nguồn; bảng `schools` KHÔNG lưu `ownership`, nên đổi phạm vi thì lọc lại từ
-- CSV chứ đừng sửa tay danh sách dưới đây.
--
-- SỐ LƯỢNG: 946. Jmix ghi 939 — chênh vì bản CSV lúc đó cũ hơn. Trong tập này
-- có 96 dòng TRÙNG TÊN và chúng được giữ nguyên: mã đều duy nhất, còn trùng
-- tên là sự thật (có 5 trường "Tiểu Học Lương Thế Vinh" ở 5 quận khác nhau),
-- nên lọc theo tên là xoá trường có thật.
--
-- CƠ QUAN CHỦ QUẢN: tất cả gán về Sở GD&ĐT, đúng như Jmix. Nguồn không nói
-- trường nào thuộc UBND nào, và cột `ward` chỉ có ở 75/946 dòng nên không suy
-- ra được. Khi Sở cung cấp bảng phân cấp quản lý thì chuyển bằng một migration
-- UPDATE — không phải nhập lại.
--
-- ĐỊA BÀN: `ward` của nguồn là TÊN phường/xã theo địa giới 2025, và chỉ điền ở
-- 75 dòng. Ghép sang khoá ngoại bằng LEFT JOIN theo tên, dòng không khớp thì
-- `ward_id` rỗng còn tên gốc giữ ở `ward_text` để đối chiếu. Cột `district` là
-- quận/huyện CŨ trước 01/07/2025 — giữ lại làm manh mối địa bàn, vì phần lớn
-- địa chỉ nguồn chưa đổi theo phường mới.
--
-- MÃ: `code` là mã đơn vị của nguồn, viết HOA. `moet_code` để RỖNG — nguồn này
-- không có mã định danh 20 ký tự của Bộ GD&ĐT. `short_code` cũng rỗng: nó là
-- thành phần sinh mã tài sản, do người dùng đặt.

-- ---------------------------------------------------------------- 1. Xoá demo
-- Xoá theo MÃ, không theo tên: tên đã bỏ tiền tố [DEMO] ở migration 047 nên
-- tên không còn là dấu hiệu nhận biết. Thứ tự: trường trước, cơ quan sau, vì
-- khoá ngoại là RESTRICT.
DELETE FROM schools WHERE code LIKE 'DEMO-%';
DELETE FROM departments_of_education WHERE code LIKE 'DEMO-UBND-%';

-- ---------------------------------------------------------------- 2. Nhập thật
INSERT INTO schools (
    department_of_education_id, education_level_id, code, name,
    district, ward_id, ward_text, address, status, created_at)
SELECT
    so.id,
    el.id,
    v.code,
    v.name,
    v.district,
    w.id,
    -- Giữ tên phường của nguồn kể cả khi đã ghép được: nó là thứ đối chiếu khi
    -- có ai hỏi vì sao một trường được gán vào phường này.
    v.ward_name,
    v.address,
    'ACTIVE',
    now()
FROM (VALUES
