JOIN education_levels el ON el.code = v.level_code
CROSS JOIN (SELECT id FROM departments_of_education WHERE code = 'SGD-HCM') AS so
LEFT JOIN wards w ON lower(w.name) = lower(v.ward_name)
WHERE NOT EXISTS (SELECT 1 FROM schools s WHERE s.code = v.code);
